package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Dirección reutilizable de un cliente, con su punto en el mapa (tabla DIRECCION, RF-M2-04 y RF-M2-05).
 * <p>
 * EN: Reusable address of a customer, with its point on the map (DIRECCION table, RF-M2-04 and RF-M2-05).
 */
@Entity
@Table(name = "DIRECCION")
public class Address {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El id del cliente. EN: The customer id. */
    @Column(name = "CLIENTE_ID", nullable = false) private Long customerId;
    /** La dirección escrita. EN: The written address. */
    @Column(name = "TEXTO", nullable = false, length = 150) private String text;
    /** El punto de referencia. EN: The landmark. */
    @Column(name = "REFERENCIA", length = 150) private String reference;
    /** La latitud. EN: The latitude. */
    @Column(name = "LAT", nullable = false) private double lat;
    /** La longitud. EN: The longitude. */
    @Column(name = "LNG", nullable = false) private double lng;
    /** Si la dirección está activa. EN: Whether the address is active. */
    @Column(name = "ACTIVO", nullable = false) private boolean active = true;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected Address() {}

    /**
     * Crea una dirección activa.
     * <p>
     * EN: Creates an active address.
     *
     * @param customerId id del cliente / customer id
     * @param text dirección escrita / written address
     * @param reference punto de referencia, puede ser null / landmark, may be null
     * @param point punto en el mapa / point on the map
     */
    public Address(Long customerId, String text, String reference, GeoPoint point) {
        this.customerId = customerId; this.text = text; this.reference = reference; this.lat = point.lat(); this.lng = point.lng();
    }

    /**
     * Desactiva la dirección.
     * <p>
     * EN: Deactivates the address.
     */
    public void deactivate() { active = false; }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el id del cliente.
     * <p>
     * EN: Returns the customer id.
     *
     * @return el id del cliente / the customer id
     */
    public Long getCustomerId() { return customerId; }

    /**
     * Devuelve la dirección escrita.
     * <p>
     * EN: Returns the written address.
     *
     * @return la dirección escrita / the written address
     */
    public String getText() { return text; }

    /**
     * Devuelve el punto de referencia.
     * <p>
     * EN: Returns the landmark.
     *
     * @return el punto de referencia / the landmark
     */
    public String getReference() { return reference; }

    /**
     * Devuelve la latitud.
     * <p>
     * EN: Returns the latitude.
     *
     * @return la latitud / the latitude
     */
    public double getLat() { return lat; }

    /**
     * Devuelve la longitud.
     * <p>
     * EN: Returns the longitude.
     *
     * @return la longitud / the longitude
     */
    public double getLng() { return lng; }

    /**
     * Devuelve el punto en el mapa.
     * <p>
     * EN: Returns the point on the map.
     *
     * @return el punto / the point
     */
    public GeoPoint point() { return new GeoPoint(lat, lng); }

    /**
     * Indica si la dirección está activa.
     * <p>
     * EN: Tells whether the address is active.
     *
     * @return true si se cumple / true if it applies
     */
    public boolean isActive() { return active; }
}
